update lessons set objective_ar='أحلّل حكاية «الميزان والذهب» الشعبية إلى عناصرها، وأحلّل شخصياتها بالموازنة بين العجوز الطيبة وجارتها الطمّاعة، وأستنتج القيم الإيجابية والسلبية فيها.' where code='AR-Y8-N-T2-L19';
update success_criteria set statement_ar='أحدّد عناصر الحكاية وأحداثها الرئيسة.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L19');
update success_criteria set statement_ar='أحلّل سمات العجوز وجارتها بالأدلة، وأبرّر الاختلاف بينهما.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L19');
update success_criteria set statement_ar='أستنتج أثر القناعة والطمع في حال الإنسان، وأقيّم قدرة القصة على الإقناع.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y8-N-T2-L19');
update lesson_summaries set content=content||'{"emoji": "⚖️", "hook": "قيل لعجوز فقيرة: خذي ما تشائين من أكياس الذهب… فأخذت كيسًا واحدًا! وماذا فعلت جارتها؟", "idea": "حكاية شعبية عن عجوز طيبة كافأها رجل غريب بكيس ذهب فقنعت به، وجارة طمّاعة كشفت السرّ بحيلة القار في الميزان وذهبت تطلب المزيد، فوجدت في أكياسها العقارب والأفاعي.", "learn": [["📖", "أقرأ الحكاية في كتابي ص 232–236."], ["🧶", "العجوز تقصد سوق الغزل مبكّرًا فتلقى رجلًا غريبًا."], ["💰", "تأخذ كيسًا واحدًا من الذهب قناعةً."], ["⚖️", "الجارة تضع القار في كفّة الميزان فتكشف الذهب."], ["🦂", "الطمع يقود الجارة إلى العقارب والأفاعي بدل الذهب."]], "quiz": [["أخذت العجوز كيسًا واحدًا مع أنها خُيّرت.", true], ["كشفت الجارة السرّ حين رأت الرجل الغريب بنفسها.", false]], "words": [["الْمِيزان", "أداة الوزن"], ["الطَّمَع", "الرغبة في أكثر من الحق"], ["الْقَناعَة", "الرضا بما قسم الله"], ["الْمَكْر", "الخداع والحيلة السيئة"]], "think": "متى جلب لي الرضا بما عندي راحةً أكثر من طلب المزيد؟"}'::jsonb where lesson_id=(select id from lessons where code='AR-Y8-N-T2-L19');